html,body { background:#0f172a !important; margin:0; padding:0; }
.app{width:100%;box-sizing:border-box;font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,sans-serif;}
.hdr{color:#f1f5f9;font-weight:700;font-size:14px;padding:10px 4px;}
.ag-theme-alpine { --ag-header-background-color:#0f172a; --ag-header-foreground-color:#FFF; --ag-odd-row-background-color:#0f172a; --ag-background-color:#1E293B; --ag-row-hover-color:#1E293B; --ag-foreground-color:#FFF; --ag-border-color:#1E293B; --ag-font-size:14px; --ag-row-height:44px; --ag-header-height:48px; border-radius:6px;border:1px solid #1E293B;overflow:hidden;}
.ag-theme-alpine .ag-row-odd{background-color:#0f172a !important;}
.ag-theme-alpine .ag-row-even{background-color:#1E293B !important;}
.ag-theme-alpine .ag-row-hover{background-color:rgba(255,255,255,0.05) !important;}
.ag-theme-alpine .ag-header-cell-text{color:#FFF;}
.detail-link{color:#60a5fa;cursor:pointer;font-weight:600;}
.pill{display:inline-flex;align-items:center;gap:7px;} .dot{width:8px;height:8px;border-radius:50%;display:inline-block;}
::-webkit-scrollbar{width:10px;height:10px;background:#0f172a;} ::-webkit-scrollbar-thumb{background:#1E293B;border-radius:4px;border:2px solid #0f172a;}

