function statusRenderer(p){ var v=p.value; var open=String(v).toLowerCase()==='open';
  var c=open?'#22c55e':(String(v).toLowerCase()==='closed'?'#ef4444':'#94a3b8');
  return '<span class="pill"><span class="dot" style="background:'+c+'"></span>'+(v==null?'':v)+'</span>'; }
var COLS=[
  {headerName:'Billing Account',field:'Billing Account',flex:1,minWidth:140},
  {headerName:'Vendor',field:'Vendor',flex:1,minWidth:150},
  {headerName:'Billing ID',field:'Billing ID',flex:1,minWidth:130},
  {headerName:'Utility',field:'Utility',width:150},
  {headerName:'Last Bill',field:'Last Bill',width:120},
  {headerName:'Open/Closed',field:'Open/Closed',width:130,cellRenderer:statusRenderer},
  {headerName:'',colId:'billhistory',field:'Billing Account',width:130,sortable:false,resizable:false,cellRenderer:function(){return '<span class="detail-link">Bill History</span>';}}
];
var gridApi=null,lastSig='';
function getRows(m){return (m&&Array.isArray(m.data))?m.data:[];}
function sig(m){var r=getRows(m);return (m&&m.isLoading?'L':'')+r.length+':'+(r[0]&&r[0]['Billing Account']);}
function setHdr(m){var h=document.getElementById('hdr');if(h)h.textContent='Billing Accounts total: '+getRows(m).length;}
function onCellClicked(e){ if(e.column&&e.column.getColId()==='billhistory'){ appsmith.updateModel({baSelected:e.data}); appsmith.triggerEvent('onBillHistory'); } }
function render(m){var el=document.querySelector('#myGrid');if(!el)return;el.innerHTML='';
  gridApi=agGrid.createGrid(el,{columnDefs:COLS,rowData:getRows(m),defaultColDef:{resizable:true,sortable:true,minWidth:90},
    animateRows:true,popupParent:document.body,getRowId:function(p){return String(p.data['Billing Account']);},
    overlayNoRowsTemplate:'<span style="color:#94a3b8;font-style:italic;">No billing accounts</span>',
    onGridReady:function(p){gridApi=p.api;},onCellClicked:onCellClicked});
  lastSig=sig(m);setHdr(m);}
appsmith.onReady(function(){render(appsmith.model);
  appsmith.onModelChange(function(m){ if(!gridApi){render(m);return;} var s=sig(m); if(s!==lastSig){lastSig=s;gridApi.setGridOption('rowData',getRows(m));setHdr(m);} });});

